import{_ as t,o as a,c as o,al as i}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Drive Modes","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_modes_rover/index.md","filePath":"en/flight_modes_rover/index.md"}'),r={name:"en/flight_modes_rover/index.md"};function n(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="drive-modes" tabindex="-1">Drive Modes <a class="header-anchor" href="#drive-modes" aria-label="Permalink to &quot;Drive Modes&quot;">​</a></h1><p>Flight modes (or more accurately &quot;Drive modes&quot; for ground vehicles) provide autopilot support to make it easier to manually drive the vehicle or to execute autonomous missions.</p><p>This section outlines all supported drive modes for <a href="./../frames_rover/">Rovers</a>.</p><p>For information on mapping RC control switches to specific modes see: <a href="./../config/flight_mode">Basic Configuration &gt; Flight Modes</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Selecting any other mode than those listed below will either stop the rover or can lead to undefined behaviour.</p></div><h2 id="manual-modes" tabindex="-1">Manual Modes <a class="header-anchor" href="#manual-modes" aria-label="Permalink to &quot;Manual Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><a href="./manual#manual-mode">Manual</a></td><td>No autopilot support. User is responsible for keeping the rover on the desired course and maintaining speed and rate of turn.</td></tr><tr><td><a href="./manual#acro-mode">Acro</a></td><td>+ Maintains the yaw rate (feels more like driving a car than manual mode). <br>+ Allows maximum yaw rate to be limited (protects against roll over).</td></tr><tr><td><a href="./manual#stabilized-mode">Stabilized</a></td><td>+ Maintains the yaw (significantly better at holding a straight line).</td></tr><tr><td><a href="./manual#position-mode">Position</a></td><td>+ Maintains the course (best mode for driving a straight line).<br>+ Maintains speed against disturbances, e.g. when driving up a hill.<br>+ Allows maximum speed to be limited.</td></tr><tr><td><a href="./manual#manual-parking-mode">Manual Parking</a></td><td>Reduced throttle for precise maneuvering in tight spaces. Differential and mecanum rovers are driven tank-style, using one stick per side. Ackermann vehicles are controlled in the same way as they are in manual mode, but with reduced throttle.</td></tr></tbody></table><h2 id="auto-modes" tabindex="-1">Auto Modes <a class="header-anchor" href="#auto-modes" aria-label="Permalink to &quot;Auto Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><a href="./auto#mission-mode">Mission</a></td><td>Automatic mode that causes the vehicle to execute a predefined mission.</td></tr><tr><td><a href="./auto#return-mode">Return</a></td><td>Automatic mode that returns the vehicle to the launch position.</td></tr></tbody></table><h2 id="failsafe-fallback-sequence" tabindex="-1">Failsafe Fallback Sequence <a class="header-anchor" href="#failsafe-fallback-sequence" aria-label="Permalink to &quot;Failsafe Fallback Sequence&quot;">​</a></h2><p>If a rover loses navigation while in an autonomous or semi-autonomous mode that relies on it, such as losing GNSS while in <strong>Position</strong> mode, PX4 will fall back to the mode that maintains the most control given the (remaining) available sensor information.</p><p>The failure cascade sequence with a manual controller available is: <strong>Position -&gt; Stabilized -&gt; Acro -&gt; Manual</strong></p><p>If manual control input is not available, the fallback cascade continues to: <strong>Hold -&gt; RTL -&gt; Disarm</strong></p><p>Note that rovers will not use unsupported multicopter modes, such as Altitude or Descend. If the failsafe system attempts to force the rover into an unsupported <code>Descend</code> state, the rover will safely bypass termination and automatically fall back to the action defined by the <code>COM_POS_FS_ACT</code> parameter.</p>',14)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
